    const res = await t.fetch("/asset.bin", { headers: { range: "bytes=0-0" } });
    expect(res.status).toBe(206);
    expect(res.headers.get("content-range")).toBe("bytes 0-0/1000");
    expect(res.headers.get("content-length")).toBe("1");
    expect(await readBytes(res)).toEqual(bytes.slice(0, 1));
  });

