import { beforeEach, vi } from "vitest";
import { serveStatic, type ServeStaticOptions, type StaticAssetMeta } from "../src/index.ts";
import { describeMatrix } from "./_setup.ts";

// Acceptance tests for h3js/h3#1267 (HTTP Range in serveStatic), derived from sdd/prd.md (RF-01 to RF-12)
// and sdd/techspec.md (D-02 to D-08).

const SIZE = 1000;
const bytes = Uint8Array.from({ length: SIZE }, (_, i) => i % 256);
const lastModified = 1_700_000_000_000;
const lastModifiedDate = new Date(lastModified).toUTCString();

const gzip = Uint8Array.from({ length: 300 }, (_, i) => (i * 7) % 256);

async function readBytes(res: Response): Promise<Uint8Array> {
  return new Uint8Array(await res.arrayBuffer());
}

describeMatrix("sdd: serveStatic Range", (t, { it, expect }) => {
  let getContents: ReturnType<typeof vi.fn>;
  let files: Record<string, { meta: StaticAssetMeta; contents: BodyInit | null }>;

  beforeEach(() => {
    files = {
      "/asset.bin": {
        meta: {
          type: "application/octet-stream",
          etag: '"abc"',
          mtime: lastModified,
          size: SIZE,
        },
        contents: bytes,
      },
      "/weak.bin": {
        meta: { etag: 'W/"abc"', mtime: lastModified, size: SIZE },
        contents: bytes,
      },
      "/nosize.bin": {
        meta: { etag: '"abc"', mtime: lastModified },
        contents: bytes,
      },
      "/zero.bin": {
        meta: { size: 0 },
        contents: bytes,
      },
      "/one.bin": {
        meta: { size: 1 },
        contents: Uint8Array.of(7),
      },
      "/app.js.gz": {
        meta: { type: "text/javascript", encoding: "gzip", size: 300 },
        contents: gzip,
      },
    };
    getContents = vi.fn((id: string) => files[id]?.contents);

    const serve = (options: Partial<ServeStaticOptions> = {}) => (event: any) =>
      serveStatic(event, {
        getMeta: (id) => files[id]?.meta,
        getContents,
        encodings: { gzip: ".gz" },
        ...options,
      });

    t.app.all("/**", serve());
    t.app.all("/strict/**", serve({ fallthrough: false }));
    t.app.all("/fall/**", serve({ fallthrough: true }));
    t.app.all("/cl/**", serve({ headers: { "content-length": "999" } }));
    t.app.post("/fall/**", async (event) => {
      const result = await serveStatic(event, {
        getMeta: (id) => files[id]?.meta,
        getContents,
        fallthrough: true,
      });
      return { passedThrough: result === undefined };
    });
  });

  // RF-01
  it("RF-01: advertises Accept-Ranges on a 200 response", async () => {
    const res = await t.fetch("/asset.bin");
    expect(res.status).toBe(200);
    expect(res.headers.get("accept-ranges")).toBe("bytes");
    expect(res.headers.get("content-range")).toBeNull();
  });

  it("RF-01: advertises Accept-Ranges on HEAD and 416 responses", async () => {
    const head = await t.fetch("/asset.bin", { method: "HEAD" });
    expect(head.headers.get("accept-ranges")).toBe("bytes");

    const unsatisfiable = await t.fetch("/asset.bin", { headers: { range: "bytes=1000-1100" } });
    expect(unsatisfiable.status).toBe(416);
    expect(unsatisfiable.headers.get("accept-ranges")).toBe("bytes");
  });

  it("RF-01 / RF-08: no Accept-Ranges on 304, 404 or 405", async () => {
    const notModified = await t.fetch("/asset.bin", {
      headers: { "if-none-match": '"abc"', range: "bytes=0-9" },
    });
    expect(notModified.status).toBe(304);
    expect(notModified.headers.get("accept-ranges")).toBeNull();

    const notFound = await t.fetch("/strict/missing.bin");
    expect(notFound.status).toBe(404);
    expect(notFound.headers.get("accept-ranges")).toBeNull();

    const notAllowed = await t.fetch("/strict/asset.bin", { method: "POST" });
    expect(notAllowed.status).toBe(405);
    expect(notAllowed.headers.get("accept-ranges")).toBeNull();
  });

  // RF-02, RF-03
  it("RF-02 / RF-03: bytes=0-99 returns the first 100 bytes as 206", async () => {
    const res = await t.fetch("/asset.bin", { headers: { range: "bytes=0-99" } });
    expect(res.status).toBe(206);
    expect(res.headers.get("content-range")).toBe("bytes 0-99/1000");
    expect(res.headers.get("content-length")).toBe("100");
    expect(await readBytes(res)).toEqual(bytes.slice(0, 100));
  });

  it("RF-03: bytes=100-199 sets the matching Content-Range", async () => {
    const res = await t.fetch("/asset.bin", { headers: { range: "bytes=100-199" } });
    expect(res.status).toBe(206);
    expect(res.headers.get("content-range")).toBe("bytes 100-199/1000");
    expect(res.headers.get("content-length")).toBe("100");
    expect(await readBytes(res)).toEqual(bytes.slice(100, 200));
  });

  it("RF-02: bytes=0-0 returns exactly one byte", async () => {
    const res = await t.fetch("/asset.bin", { headers: { range: "bytes=0-0" } });
    expect(res.status).toBe(206);
    expect(res.headers.get("content-range")).toBe("bytes 0-0/1000");
    expect(res.headers.get("content-length")).toBe("1");
    expect(await readBytes(res)).toEqual(bytes.slice(0, 1));
  });

  it("RF-02: open-ended bytes=500- returns the rest of the asset", async () => {
    const res = await t.fetch("/asset.bin", { headers: { range: "bytes=500-" } });
    expect(res.status).toBe(206);
    expect(res.headers.get("content-range")).toBe("bytes 500-999/1000");
    expect(await readBytes(res)).toEqual(bytes.slice(500));
  });

  it("RF-02: suffix bytes=-100 returns the last 100 bytes", async () => {
    const res = await t.fetch("/asset.bin", { headers: { range: "bytes=-100" } });
    expect(res.status).toBe(206);
    expect(res.headers.get("content-range")).toBe("bytes 900-999/1000");
    expect(res.headers.get("content-length")).toBe("100");
    expect(await readBytes(res)).toEqual(bytes.slice(900));
  });

  // RF-04
  it("RF-04: HEAD with a valid Range returns 206 headers and no body", async () => {
    const res = await t.fetch("/asset.bin", {
      method: "HEAD",
      headers: { range: "bytes=0-9" },
    });
    expect(res.status).toBe(206);
    expect(res.headers.get("content-range")).toBe("bytes 0-9/1000");
    expect(res.headers.get("content-length")).toBe("10");
    expect(await res.text()).toBe("");
    expect(getContents).not.toHaveBeenCalled();
  });

  // RF-05
  it("RF-05: a start past the end returns 416 without a body", async () => {
    const res = await t.fetch("/asset.bin", { headers: { range: "bytes=1000-1100" } });
    expect(res.status).toBe(416);
    expect(res.headers.get("content-range")).toBe("bytes */1000");
    expect(res.headers.get("content-length")).toBe("0");
    expect(await res.text()).toBe("");
    expect(getContents).not.toHaveBeenCalled();
  });

  it("RF-05: a zero-length suffix bytes=-0 returns 416", async () => {
    const res = await t.fetch("/asset.bin", { headers: { range: "bytes=-0" } });
    expect(res.status).toBe(416);
    expect(res.headers.get("content-range")).toBe("bytes */1000");
    expect(res.headers.get("content-length")).toBe("0");
  });

  // RF-06
  it.each([
    ["multiple ranges", "bytes=0-1,5-9"],
    ["another unit", "items=0-9"],
    ["reversed bounds", "bytes=5-2"],
    ["no bounds", "bytes=-"],
    ["non-numeric", "bytes=abc"],
  ])("RF-06: ignores an unusable Range (%s) and returns the full asset", async (_, range) => {
    const res = await t.fetch("/asset.bin", { headers: { range } });
    expect(res.status).toBe(200);
    expect(res.headers.get("content-range")).toBeNull();
    expect(await readBytes(res)).toEqual(bytes);
  });

  // RF-07
  it("RF-07: If-Range with the matching strong ETag honors the Range", async () => {
    const res = await t.fetch("/asset.bin", {
      headers: { range: "bytes=0-9", "if-range": '"abc"' },
    });
    expect(res.status).toBe(206);
    expect(await readBytes(res)).toEqual(bytes.slice(0, 10));
  });

  it("RF-07: If-Range with a different ETag returns the full asset", async () => {
    const res = await t.fetch("/asset.bin", {
      headers: { range: "bytes=0-9", "if-range": '"outra"' },
    });
    expect(res.status).toBe(200);
    expect(res.headers.get("content-range")).toBeNull();
    expect(await readBytes(res)).toEqual(bytes);
  });

  it("RF-07: a weak ETag never satisfies If-Range", async () => {
    const res = await t.fetch("/weak.bin", {
      headers: { range: "bytes=0-9", "if-range": 'W/"abc"' },
    });
    expect(res.status).toBe(200);
    expect(res.headers.get("content-range")).toBeNull();
  });

  it("RF-07: If-Range with the matching Last-Modified date honors the Range", async () => {
    const res = await t.fetch("/asset.bin", {
      headers: { range: "bytes=0-9", "if-range": lastModifiedDate },
    });
    expect(res.status).toBe(206);
    expect(res.headers.get("content-range")).toBe("bytes 0-9/1000");
  });

  it("RF-07: If-Range with a different date returns the full asset", async () => {
    const res = await t.fetch("/asset.bin", {
      headers: {
        range: "bytes=0-9",
        "if-range": new Date(lastModified - 60_000).toUTCString(),
      },
    });
    expect(res.status).toBe(200);
    expect(res.headers.get("content-range")).toBeNull();
  });

  // RF-08
  it("RF-08: a 304 wins over Range", async () => {
    const res = await t.fetch("/asset.bin", {
      headers: { "if-none-match": '"abc"', range: "bytes=0-9" },
    });
    expect(res.status).toBe(304);
    expect(res.headers.get("content-range")).toBeNull();
    expect(await res.text()).toBe("");
  });

  // RF-09
  it("RF-09: an end past the size is clamped to size - 1", async () => {
    const res = await t.fetch("/asset.bin", { headers: { range: "bytes=900-5000" } });
    expect(res.status).toBe(206);
    expect(res.headers.get("content-range")).toBe("bytes 900-999/1000");
    expect(res.headers.get("content-length")).toBe("100");
    expect(await readBytes(res)).toEqual(bytes.slice(900));
  });

  it("RF-09: a suffix longer than the asset returns the whole asset as 206", async () => {
    const res = await t.fetch("/asset.bin", { headers: { range: "bytes=-5000" } });
    expect(res.status).toBe(206);
    expect(res.headers.get("content-range")).toBe("bytes 0-999/1000");
    expect(res.headers.get("content-length")).toBe("1000");
    expect(await readBytes(res)).toEqual(bytes);
  });

  it("RF-09: the last byte bytes=999-999 is served", async () => {
    const res = await t.fetch("/asset.bin", { headers: { range: "bytes=999-999" } });
    expect(res.status).toBe(206);
    expect(res.headers.get("content-range")).toBe("bytes 999-999/1000");
    expect(await readBytes(res)).toEqual(bytes.slice(999));
  });

  // RF-10
  it.each([
    ["without size", "/nosize.bin"],
    ["with size 0", "/zero.bin"],
  ])("RF-10: ignores Range when the asset has no usable size (%s)", async (_, path) => {
    const res = await t.fetch(path, { headers: { range: "bytes=0-9" } });
    expect(res.status).toBe(200);
    expect(res.headers.get("content-range")).toBeNull();
  });

  it("RF-10: a one-byte asset serves bytes=0- and bytes=0-0 identically", async () => {
    for (const range of ["bytes=0-", "bytes=0-0"]) {
      const res = await t.fetch("/one.bin", { headers: { range } });
      expect(res.status).toBe(206);
      expect(res.headers.get("content-range")).toBe("bytes 0-0/1");
      expect(res.headers.get("content-length")).toBe("1");
      expect(await readBytes(res)).toEqual(Uint8Array.of(7));
    }
  });

  // RF-11
  it("RF-11: Range applies to the selected precompressed variant", async () => {
    const res = await t.fetch("/app.js", {
      headers: { "accept-encoding": "gzip", range: "bytes=0-9" },
    });
    expect(res.status).toBe(206);
    expect(res.headers.get("content-encoding")).toBe("gzip");
    expect(res.headers.get("content-range")).toBe("bytes 0-9/300");
    expect(res.headers.get("content-length")).toBe("10");
    expect(await readBytes(res)).toEqual(gzip.slice(0, 10));
  });

  // RF-12
  it("RF-12: a missing asset with fallthrough: false still returns 404", async () => {
    const res = await t.fetch("/strict/missing.bin");
    expect(res.status).toBe(404);
  });

  it("RF-12: a POST with fallthrough: true returns undefined and the chain continues", async () => {
    const res = await t.fetch("/fall/asset.bin", { method: "POST" });
    expect(await res.json()).toEqual({ passedThrough: true });
  });

  // D-05
  it("D-05: options.headers content-length still applies to a HEAD 200", async () => {
    const res = await t.fetch("/cl/asset.bin", { method: "HEAD" });
    expect(res.status).toBe(200);
    expect(res.headers.get("content-length")).toBe("999");
  });

  it("D-05: a HEAD 206 overrides options.headers content-length with the slice length", async () => {
    const res = await t.fetch("/cl/asset.bin", {
      method: "HEAD",
      headers: { range: "bytes=0-9" },
    });
    expect(res.status).toBe(206);
    expect(res.headers.get("content-length")).toBe("10");
    expect(res.headers.get("content-range")).toBe("bytes 0-9/1000");
  });
});

describeMatrix("sdd: serveStatic Range body types", (t, { it, expect }) => {
  const text = "héllo wörld";
  const textBytes = new TextEncoder().encode(text);
  const expected = textBytes.slice(2, 6);

  function serveWith(contents: () => BodyInit) {
    return (event: any) =>
      serveStatic(event, {
        getMeta: () => ({ type: "application/octet-stream", size: textBytes.length }),
        getContents: contents,
      });
  }

  it("string bodies are sliced by bytes, not characters", async () => {
    t.app.all("/**", serveWith(() => text));
    const res = await t.fetch("/a.bin", { headers: { range: "bytes=2-5" } });
    expect(res.status).toBe(206);
    expect(await readBytes(res)).toEqual(expected);
  });

  it("Blob bodies are sliced to the requested range", async () => {
    t.app.all("/**", serveWith(() => new Blob([textBytes])));
    const res = await t.fetch("/a.bin", { headers: { range: "bytes=2-5" } });
    expect(res.status).toBe(206);
    expect(await readBytes(res)).toEqual(expected);
  });

  it("ArrayBuffer bodies are sliced to the requested range", async () => {
    t.app.all("/**", serveWith(() => textBytes.slice().buffer));
    const res = await t.fetch("/a.bin", { headers: { range: "bytes=2-5" } });
    expect(res.status).toBe(206);
    expect(await readBytes(res)).toEqual(expected);
  });

  it("Uint8Array views with a non-zero byteOffset are sliced from the view", async () => {
    const backing = new Uint8Array(textBytes.length + 16);
    backing.set(textBytes, 16);
    const view = backing.subarray(16, 16 + textBytes.length);
    t.app.all("/**", serveWith(() => view));
    const res = await t.fetch("/a.bin", { headers: { range: "bytes=2-5" } });
    expect(res.status).toBe(206);
    expect(await readBytes(res)).toEqual(expected);
  });

  it("ReadableStream bodies are sliced and the stream is cancelled after the range", async () => {
    let cancelled = false;
    const stream = new ReadableStream<Uint8Array>({
      start(controller) {
        controller.enqueue(textBytes.slice(0, 3));
        controller.enqueue(textBytes.slice(3));
      },
      cancel() {
        cancelled = true;
      },
    });
    t.app.all("/**", serveWith(() => stream));
    const res = await t.fetch("/a.bin", { headers: { range: "bytes=2-5" } });
    expect(res.status).toBe(206);
    expect(await readBytes(res)).toEqual(expected);
    expect(cancelled).toBe(true);
  });
});

